from __future__ import annotations
from typing import Callable, Sequence

def perturb(f: Callable[[complex], complex], sample: Sequence[complex], z: complex, target: complex) -> Callable[[complex], complex]:
    def p(w: complex) -> complex:
        out = 1 + 0j
        for a in sample:
            out *= w - a
        return out
    if p(z) == 0:
        raise ValueError("fresh point lies in sample")
    scale = (target - f(z)) / p(z)
    return lambda w: f(w) + scale * p(w)

if __name__ == "__main__":
    f = lambda w: w*w + 1
    sample = [0j, 1+0j, 1j]
    z = 2+1j
    g = perturb(f, sample, z, 0j)
    print([abs(g(a)-f(a)) for a in sample], abs(g(z)))

from __future__ import annotations
from typing import Callable

def first_nonzero(jet: Callable[[int], complex], bound: int, tol: float = 1e-12) -> int:
    for k in range(bound + 1):
        if abs(jet(k)) > tol:
            return k
    raise ValueError("the supplied bound has no nonzero witness")

if __name__ == "__main__":
    jet = lambda k: 0j if k < 4 else 1+0j
    print(first_nonzero(jet, 10))

from __future__ import annotations

def certify(n: int, d: int) -> bool:
    return n >= 2 and 1 < d < n and n % d == 0

def decode_and_certify(n: int, oracle_answer: int) -> int:
    d = oracle_answer
    if not certify(n, d):
        raise ValueError("decoder output is not a proper divisor")
    return d

if __name__ == "__main__":
    print(decode_and_certify(221, 13))

